require_once __DIR__.'/../../config/conexion.php';require_once __DIR__.'/../Models/PlanillaEstadoModel.php';class PlanillaEstadoController{private function m(){global $conexion;return new PlanillaEstadoModel($conexion);}function aprobar():void{autorizar('planilla.calcular');validarCsrf();$id=(int)($_POST['id_periodo_pago']??0);try{$this->m()->aprobar($id,(int)$_SESSION['usuario']['id_usuario']);mensaje('success','Revisión aprobada. La planilla quedó protegida.');}catch(Throwable $e){mensaje('error',$e->getMessage());}header('Location:index.php?url=planilla_revision&id='.$id);exit;}function cerrar():void{autorizar('planilla.cerrar');validarCsrf();$id=(int)($_POST['id_periodo_pago']??0);try{$this->m()->cerrar($id,(int)$_SESSION['usuario']['id_usuario']);mensaje('success','Planilla cerrada correctamente.');}catch(Throwable $e){mensaje('error',$e->getMessage());}header('Location:index.php?url=planilla_revision&id='.$id);exit;}}
